// What only a terminal's stream has, and what the tty module says.
var out = process.stdout;
module.exports = {
  depth: typeof out.getColorDepth,
  colours: typeof out.hasColors === "function",
  sized: out.columns !== undefined && out.rows !== undefined,
  window: "getWindowSize" in out,
  isatty: require("tty").isatty(1),
  error: require("tty").isatty(2),
};
